// Tipos de unidad que consumen y reportan diesel, y por lo tanto se rastrean en el módulo de
// Control de Diesel (dashboard, captura, asignación). "Rabón" todavía no es un tipo seleccionable
// en el catálogo (no se agregó a TIPOS arriba), pero en cuanto exista una unidad con este tipo,
// el módulo de Diesel — incluida la clasificación de operadores por tipo y Business Unit — la
// tomará en cuenta automáticamente sin más cambios de código.
const DIESEL_TIPOS = ["Tractor", "Rabón"];
// Nombre en plural mostrado como encabezado de cada bloque de clasificación de operadores
// en el Dashboard de Diesel (p. ej. "TRACTORES"). Si aparece un tipo nuevo que no está aquí,
// se usa "<tipo>s" como respaldo automático.
const TIPO_DIESEL_PLURAL = { "Tractor": "Tractores", "Rabón": "Rabones" };
const ESTATUS = ["Activo", "En taller", "Fuera de servicio", "Baja"];
// Catálogo fijo de unidades de negocio -- antes "Unidad de negocio" era texto libre, lo que dejaba
// que la misma unidad quedara escrita de formas distintas (mayúsculas, espacios, etc.) y rompiera el
// filtro del catálogo. Un valor ya capturado que no esté en esta lista (p. ej. "XBC"/"XBCF" de datos
// anteriores) no se pierde: el formulario lo sigue mostrando como opción aparte, marcado como tal.
const BUSINESS_UNIT_OPTIONS = ["XBW", "XBW-US", "US Local", "US OTR", "OTR", "Local MX XBC", "Local MX XBCF", "Local XBW"];
// Unidades de negocio que operan en EU: sus tractocamiones sí traen placa americana. El resto
// de unidades de negocio son nacionales y no la traen -- para esos tractocamiones el campo
// "Placas US" se normaliza a "N/A" (ver normalizarPlacaAmericana más abajo).
const US_PLATE_BUSINESS_UNITS = ["US Local", "US OTR", "OTR"];
function aplicaPlacaAmericana(tipo, businessUnit) {
  if (tipo !== "Tractor") return false;
  const bu = (businessUnit || "").trim().toLowerCase();
  return US_PLATE_BUSINESS_UNITS.some((opt) => opt.toLowerCase() === bu);
}
function normalizarPlacaAmericana(unit) {
  if (unit.tipo !== "Tractor") return unit;
  if (aplicaPlacaAmericana(unit.tipo, unit.businessUnit)) return unit;
  if (unit.placasUs === "N/A") return unit;
  return { ...unit, placasUs: "N/A" };
}
// Placa para mostrar en reportes que solo tienen espacio para una columna de "Placas": prioriza
// la US cuando es una placa real (los remolques solo traen esta), y cae a la MX -- "N/A" no cuenta
// como placa real, así que un tractocamión nacional (ver normalizarPlacaAmericana) muestra su MX.
function placaParaReporte(unit) {
  if (unit.placasUs && unit.placasUs !== "N/A") return unit.placasUs;
  return unit.placas || "—";
}
const SEGURO_PAISES = ["USA", "MX"];
const DIESEL_SECCIONES = ["Dashboard de Diesel", "Asignación de Diesel", "Captura de Diesel"];

// ---------------------------------------------------------------------------
