// ---------------------------------------------------------------------------
// Mientras no exista un login real, el rol se toma del parámetro ?role= en la URL
// (ver useState de `session` en App). Cada rol tiene un set fijo de permisos, definido
// aquí en un solo lugar para que la tabla de permisos confirmada con Tecma sea fácil
// de auditar y ajustar sin tener que rastrear condicionales sueltas por todo el archivo.
const ROLES = ["Admin", "Tráfico", "Mantenimiento", "Operador"];

const PERMISOS_POR_ROL = {
  Admin: [
    "unidades.agregar",       // Agregar unidad / Actualizar datos en lote (Excel)
    "catalogo.editarTodo",    // Editar todos los datos del catálogo / Eliminar unidad
    "catalogo.edicionRapida", // Estatus, ubicación, operador asignado
    "mantenimiento.ver",      // Pestaña Mantenimiento (llantas, mantenimiento preventivo)
    "inspeccion.ver",         // Pestaña Inspección diaria (DVIR)
    "diesel.asignar",         // Asignación de Diesel
    "diesel.capturar",        // Captura de Diesel
    "solicitudes.crear",      // Solicitar asignación / préstamo de unidad
    "solicitudes.aprobar",    // Aprobar/rechazar solicitudes de asignación/préstamo
    "operadores.editar",      // Alta/edición del catálogo de Operadores
  ],
  "Tráfico": [
    "catalogo.edicionRapida",
    "diesel.asignar",
    "solicitudes.crear",
  ],
  Mantenimiento: [
    "mantenimiento.ver",
    "inspeccion.ver",
  ],
  Operador: [
    "inspeccion.ver",
  ],
};

function tienePermiso(role, permiso) {
  return (PERMISOS_POR_ROL[role] || []).includes(permiso);
}

// Id simple para registros creados en el navegador (solicitudes, operadores, fotos de daño)
// que todavía no tienen un id real de Supabase -- no requiere ninguna librería extra.
function genId() {
  return Date.now().toString(36) + Math.random().toString(36).slice(2, 9);
}

// ---------------------------------------------------------------------------
// Catálogo de Operadores
// ---------------------------------------------------------------------------
const OPERADOR_ESTATUS = ["Activo", "Inactivo"];
// Sugerencias para el campo "Clasificación" (no es una lista cerrada -- se puede escribir
// cualquier valor; esto solo ayuda a mantener consistencia si ya usan estas categorías).
const OPERADOR_CLASIFICACIONES_SUGERIDAS = ["Local", "Regional", "OTR", "Interno", "Subcontratado"];

function operadorToRow(op) {
  return { id: op.id, nombre: op.nombre || "", clasificacion: op.clasificacion || "", estatus: op.estatus || "Activo" };
}
function rowToOperador(row) {
  return { id: row.id, nombre: row.nombre || "", clasificacion: row.clasificacion || "", estatus: row.estatus || "Activo" };
}
// El catálogo de Operadores es nuevo -- se siembra con los nombres que ya estaban capturados
// como texto libre en el campo "Operador" de las unidades semilla, para que las unidades que
// ya traen alguien asignado no se queden sin coincidencia al pasar ese campo a un desplegable.
function buildSeedOperadores(units) {
  const nombres = Array.from(new Set((units || []).map((u) => (u.operador || "").trim()).filter(Boolean)));
  return nombres.sort((a, b) => a.localeCompare(b, "es")).map((nombre) => ({ id: genId(), nombre, clasificacion: "", estatus: "Activo" }));
}

