const SOLICITUD_ESTATUS = ["Pendiente", "Aprobada", "Rechazada"];

// ---------------------------------------------------------------------------
// Validación de datos (Catálogo)
// ---------------------------------------------------------------------------
// VIN estándar: 17 caracteres. Algunas unidades semilla antiguas pueden no cumplirlo -- esto
// solo bloquea el GUARDADO de un formulario, no altera datos ya existentes que no se toquen.
function vinValido(vin) {
  return (vin || "").trim().length === 17;
}
function validarUnidad(form, existingEconomicos) {
  const errores = {};
  const economico = (form.numeroEconomico || "").trim();
  if (!economico) errores.numeroEconomico = "Requerido";
  else if ((existingEconomicos || []).some((e) => (e || "").trim().toLowerCase() === economico.toLowerCase())) {
    errores.numeroEconomico = "Ya existe otra unidad con este número económico";
  }
  const vin = (form.vin || "").trim();
  if (!vin) errores.vin = "Requerido";
  else if (!vinValido(vin)) errores.vin = `El VIN debe tener 17 caracteres (tiene ${vin.length})`;
  return errores;
}

// ---------------------------------------------------------------------------
// Fotos de daño en inspección: se comprimen en el navegador (canvas) antes de guardarse
// para no llenar de datos pesados cada inspección -- una foto de celular de 3-5 MB queda
// normalmente en 100-300 KB sin que se note pérdida de calidad para ver el daño.
// ---------------------------------------------------------------------------
function comprimirImagen(file, maxAncho = 1280, calidad = 0.75) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onerror = () => reject(new Error("No se pudo leer la imagen."));
    reader.onload = () => {
      const img = new Image();
      img.onerror = () => reject(new Error("No se pudo procesar la imagen."));
      img.onload = () => {
        const escala = Math.min(1, maxAncho / img.width);
        const w = Math.round(img.width * escala);
        const h = Math.round(img.height * escala);
        const canvas = document.createElement("canvas");
        canvas.width = w;
        canvas.height = h;
        const ctx = canvas.getContext("2d");
        ctx.drawImage(img, 0, 0, w, h);
        resolve(canvas.toDataURL("image/jpeg", calidad));
      };
      img.src = reader.result;
    };
    reader.readAsDataURL(file);
  });
}

