const MTTO_INTERVALO = 25000; // millas entre mantenimientos preventivos (Tractor)
// Dry Van y Flatbed son remolques: no tienen motor ni odómetro propio (su kilometraje va ligado
// al tractor que los jala en cada viaje, no a ellos mismos), así que su mantenimiento preventivo
// se controla por tiempo transcurrido en vez de millas recorridas.
const MTTO_INTERVALO_MESES_TRAILER = 6; // meses entre mantenimientos preventivos (Dry Van / Flatbed)

function odometroActualDe(unit) {
  const hist = unit.odometroHistorial || [];
  return hist.length > 0 ? hist[0].lectura : (unit.odometro || 0);
}
function mantenimientoStatus(unit) {
  const historial = unit.mantenimientoHistorial || [];
  // Solo los registros de tipo "Preventivo" reinician el contador del intervalo; una
  // "Reparación" queda en el historial pero no cuenta como servicio programado (los
  // registros sin tipo, de antes de este campo, se tratan como Preventivo).
  const preventivos = historial.filter((m) => (m.tipo || "Preventivo") === "Preventivo");
  const ultimo = preventivos.length > 0 ? preventivos[0] : null;
  const porFecha = unit.tipo === "Dry Van" || unit.tipo === "Flatbed";
  if (porFecha) {
    if (!ultimo) return { pendiente: false, sinRegistro: true, porFecha, mesesTranscurridos: null, ultimo: null };
    const mesesTranscurridos = (Date.now() - new Date(ultimo.fecha).getTime()) / (1000 * 60 * 60 * 24 * 30.44);
    const pendiente = mesesTranscurridos >= MTTO_INTERVALO_MESES_TRAILER;
    const proximo = !pendiente && MTTO_INTERVALO_MESES_TRAILER - mesesTranscurridos <= 1;
    return { pendiente, proximo, sinRegistro: false, porFecha, mesesTranscurridos, ultimo };
  }
  const actual = odometroActualDe(unit);
  if (!ultimo) return { pendiente: false, sinRegistro: true, porFecha, diff: null, restante: null, ultimo: null, actual };
  const diff = actual - ultimo.odometro;
  const restante = MTTO_INTERVALO - diff;
  const pendiente = diff >= MTTO_INTERVALO;
  const proximo = !pendiente && restante <= 2000;
  return { pendiente, proximo, sinRegistro: false, porFecha, diff, restante, ultimo, actual };
}

function daysUntil(dateStr) {
  const ms = new Date(dateStr + "T00:00:00") - new Date(new Date().toDateString());
  return Math.round(ms / 86400000);
}
function urgencyOf(days) {
  if (days < 0) return "vencido";
  if (days <= 7) return "urgente";
  if (days <= 30) return "proximo";
  return "ok";
}
