// Tabla de relevancia del DVIR: la calificación parte de 100 y resta el peso de cada ítem marcado
// como "falla" (en vez de la regla anterior, donde una sola falla -- sin importar cuál -- tumbaba
// toda la inspección). Frenos y llantas pesan más por ser los más críticos para operar con
// seguridad; documentos a bordo se subió a 10 (antes 5) a petición explícita, recortando esos
// puntos de Espejos (antes 10, ahora 5) para mantener el total en 100.
const INSPECCION_PESOS = {
  "Frenos": 25,
  "Llantas y rines": 20,
  "Luces y direccionales": 15,
  "Documentos a bordo": 10,
  "Niveles de fluidos": 10,
  "Extintor": 8,
  "Triángulos de seguridad": 7,
  "Espejos": 5,
};
const INSPECCION_APTA_UMBRAL = 75; // arriba de este puntaje, la unidad se marca "Apta para laborar"
function calificacionInspeccion(items) {
  let score = 100;
  Object.entries(items || {}).forEach(([item, val]) => {
    if (val === "falla") score -= INSPECCION_PESOS[item] || 0;
  });
  return Math.max(0, score);
}
function estadoInspeccion(calificacion) {
  return calificacion > INSPECCION_APTA_UMBRAL ? "Apta para laborar" : "No apta";
}
// Compatible con inspecciones guardadas antes de este cambio (estado "Aprobada"/"Con fallas",
// sin campo `calificacion`): solo los estados "malos", viejos o nuevos, se consideran no aptos.
function inspeccionEsApta(insp) {
  if (!insp) return true;
  return insp.estado !== "Con fallas" && insp.estado !== "No apta";
}
const NIVEL_DIESEL_OPTIONS = ["Lleno (F)", "7/8", "3/4", "5/8", "1/2", "3/8", "1/4", "1/8", "Vacío (E)"];
const NIVEL_DIESEL_ALERTA = ["3/8", "1/4", "1/8"];
// Se recalcula siempre a partir del nivel guardado (no del flag `dieselBajo` que se guardó en su momento),
// así una inspección vieja también dispara la alerta si su nivel cae dentro del umbral actual.
function dieselBajoDe(insp) {
  return !!insp && NIVEL_DIESEL_ALERTA.includes(insp.nivelDiesel);
}
function ultimaInspeccionDe(unit) {
  const insp = unit.inspecciones || [];
  return insp.length > 0 ? insp[0] : null;
}
