const fmtDate = (d) => new Date(d + "T00:00:00").toLocaleDateString("es-MX", { day: "2-digit", month: "short", year: "numeric" });
// Fecha + hora exacta (para inspecciones: cuándo se capturó, no solo qué día) -- a diferencia
// de fmtDate, este recibe un timestamp ISO completo (con hora), no una fecha "YYYY-MM-DD".
const fmtFechaHora = (iso) => new Date(iso).toLocaleString("es-MX", { day: "2-digit", month: "short", year: "numeric", hour: "2-digit", minute: "2-digit" });

// ---------------------------------------------------------------------------
// Reporte de Alertas: "Formato de autorización para renovación" -- se genera desde la vista
// Alertas (por cada vencimiento próximo/urgente/vencido, o de todos juntos) como una página
// imprimible/PDF (usa el diálogo de impresión del navegador, "Guardar como PDF"), lista para que
// el gerente de flota la firme físicamente antes de tramitar la renovación.
// ---------------------------------------------------------------------------
function escapeHtml(s) {
  return String(s ?? "").replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
}
function autorizacionRowHTML(a) {
  const diasTxt = a.days < 0 ? `Vencido hace ${-a.days} día${-a.days === 1 ? "" : "s"}` : `Vence en ${a.days} día${a.days === 1 ? "" : "s"}`;
  return `<tr>
    <td>${escapeHtml(a.unit.numeroEconomico)}</td>
    <td>${escapeHtml(a.unit.tipo)}</td>
    <td>${escapeHtml(a.unit.vin || "—")}</td>
    <td>${escapeHtml(placaParaReporte(a.unit))}</td>
    <td>${escapeHtml(a.label)}</td>
    <td>${escapeHtml(fmtDate(a.date))}</td>
    <td>${escapeHtml(diasTxt)}</td>
    <td>${escapeHtml(URGENCY_LABEL[a.urgency] || "")}</td>
  </tr>`;
}
