// Convierte cualquier valor de un registro de historial a texto seguro para mostrar.
// Blindaje por si ya quedó guardado un arreglo/objeto de una versión anterior con el bug.
function fmtHistValor(v) {
  if (v === null || v === undefined || v === "") return "—";
  if (Array.isArray(v)) return `${v.length} registro${v.length === 1 ? "" : "s"}`;
  if (typeof v === "object") return "actualizado";
  return String(v);
}

