// Categorías para ACTUALIZAR unidades existentes (solo los campos de esa categoría se tocan).
function categoriasActualizarPara(tipo) {
  if (tipo === "Tractor") {
    return [
      { id: "generales", label: "Datos generales", columns: CAMPOS_TRACTOR_GENERALES },
      { id: "seguros", label: "Seguros (aseguradora, póliza, vencimiento)", columns: CAMPOS_TRACTOR_SEGUROS },
      { id: "vencimientos", label: "Vencimientos y documentos", columns: CAMPOS_TRACTOR_VENCIMIENTOS },
    ];
  }
  const base = [{ id: "generales", label: "Datos generales", columns: CAMPOS_TRAILER_GENERALES }];
  if (tipo === "Dry Van") base.push({ id: "caracteristicas", label: "Características", columns: CAMPOS_DRYVAN_CARACTERISTICAS });
  return base;
}
// Columnas completas para AGREGAR unidades nuevas de ese tipo (una unidad nueva necesita todo).
function columnasAltaPara(tipo) {
  if (tipo === "Tractor") {
    return [
      { header: "Configuración", field: "configuracion" },
      ...CAMPOS_TRACTOR_GENERALES,
      ...CAMPOS_TRACTOR_SEGUROS,
      ...CAMPOS_TRACTOR_VENCIMIENTOS,
      { header: "Meta diesel (mi/gal)", field: "dieselMeta" },
      { header: "Notas", field: "notas" },
    ];
  }
  const cols = [...CAMPOS_TRAILER_GENERALES];
  if (tipo === "Dry Van") cols.push(...CAMPOS_DRYVAN_CARACTERISTICAS);
  cols.push({ header: "Notas", field: "notas" });
  return cols;
}
const CATEGORIA_SEGUROS = (pais) => [{
  id: "polizas",
  label: `Pólizas y vigencias (Seguro ${pais})`,
  columns: pais === "USA" ? [
    { header: "Aseguradora", field: "seguroUsaAseguradora" },
    { header: "N° de póliza", field: "seguroUsaPoliza" },
    { header: "Vencimiento", field: "seguroUsaVencimiento" },
    { header: "Radio de cobertura", field: "seguroUsaRadioCobertura" },
  ] : [
    { header: "Aseguradora", field: "seguroMxAseguradora" },
    { header: "N° de póliza", field: "seguroMxPoliza" },
    { header: "Vencimiento", field: "seguroMxVencimiento" },
  ],
}];

function parseDelimited(text) {
  const lines = text.split(/\r\n|\n|\r/).filter((l) => l.trim().length > 0);
  if (lines.length === 0) return [];
  const delim = lines[0].includes("\t") ? "\t" : ",";
  const splitLine = (line) => line.split(delim).map((c) => c.trim());
  const headers = splitLine(lines[0]);
  return lines.slice(1).map((line) => {
    const cells = splitLine(line);
    const obj = {};
    headers.forEach((h, i) => { obj[h] = cells[i] ?? ""; });
    return obj;
  });
}

let sheetJsPromise = null;
function cargarSheetJS() {
  if (window.XLSX) return Promise.resolve();
  if (!sheetJsPromise) {
    sheetJsPromise = new Promise((resolve, reject) => {
      const script = document.createElement("script");
      script.src = "https://cdnjs.cloudflare.com/ajax/libs/xlsx/0.18.5/xlsx.full.min.js";
      script.onload = () => resolve();
      script.onerror = () => { sheetJsPromise = null; reject(new Error("No se pudo cargar el lector de Excel (revisa tu conexión a internet).")); };
      document.head.appendChild(script);
    });
  }
  return sheetJsPromise;
}

async function leerArchivoTabular(file) {
  const nombre = file.name.toLowerCase();
  if (nombre.endsWith(".xlsx") || nombre.endsWith(".xls")) {
    await cargarSheetJS();
    const buf = await file.arrayBuffer();
    const wb = window.XLSX.read(buf, { type: "array" });
    const sheet = wb.Sheets[wb.SheetNames[0]];
    return window.XLSX.utils.sheet_to_json(sheet, { defval: "" });
  }
  const text = await file.text();
  return parseDelimited(text);
}

// modo: "actualizar" (empareja por Número económico y solo cambia la categoría elegida) o
// "agregar" (cada fila nueva -- con Número económico que no exista ya -- se da de alta tal cual).
function ActualizarDatosModal({ tipo, pais, units, allUnits, onClose, onBulkUpdate, onBulkAdd }) {
  const permiteAgregar = !!onBulkAdd;
  const [modo, setModo] = useState("actualizar");
  const categoriasActualizar = pais ? CATEGORIA_SEGUROS(pais) : categoriasActualizarPara(tipo);
  const [categoriaId, setCategoriaId] = useState(categoriasActualizar[0]?.id);
  const categoria = categoriasActualizar.find((c) => c.id === categoriaId) || categoriasActualizar[0];
  const columnasAlta = tipo ? columnasAltaPara(tipo) : [];

  const [estadoCopiar, setEstadoCopiar] = useState("idle");
  const [cargando, setCargando] = useState(false);
  const [resultado, setResultado] = useState(null);
  const fileInputRef = useRef(null);

  const columnas = modo === "agregar" ? columnasAlta : (categoria ? categoria.columns : []);
  const headers = ["Número económico", ...columnas.map((c) => c.header)];
  const rows = modo === "agregar"
    ? [["EJEMPLO-001", ...columnas.map((c) => (c.field === "estatus" ? "Activo" : c.field === "anio" ? new Date().getFullYear() : ""))]]
    : units.map((u) => [u.numeroEconomico, ...columnas.map((c) => u[c.field] ?? "")]);

  const copiarPlantilla = async () => {
    try {
      await copiarTablaAlPortapapeles(headers, rows);
      setEstadoCopiar("copiado");
    } catch (e) {
      console.error("No se pudo copiar la plantilla", e);
      setEstadoCopiar("error");
    } finally {
      setTimeout(() => setEstadoCopiar("idle"), 2200);
    }
  };

  const procesarArchivo = async (file) => {
    setCargando(true);
    setResultado(null);
    try {
      const filas = await leerArchivoTabular(file);
      const claveEconomico = Object.keys(filas[0] || {}).find((k) => k.trim().toLowerCase().startsWith("número económico") || k.trim().toLowerCase().startsWith("numero economico")) || "Número económico";

      if (modo === "agregar") {
        const existentes = new Set(allUnits.map((u) => u.numeroEconomico));
        const nuevas = [];
        const yaExisten = [];
        const sinNumero = [];
        filas.forEach((fila) => {
          const eco = String(fila[claveEconomico] ?? "").trim();
          if (!eco) { sinNumero.push(fila); return; }
          if (existentes.has(eco)) { yaExisten.push(eco); return; }
          existentes.add(eco); // evita duplicados dentro del mismo archivo también
          const nueva = { numeroEconomico: eco, tipo, historial: [] };
          columnasAlta.forEach((c) => {
            const val = fila[c.header];
            nueva[c.field] = val === undefined ? "" : String(val).trim();
          });
          nuevas.push(nueva);
        });
        if (nuevas.length > 0) onBulkAdd(nuevas);
        setResultado({ modo, agregadas: nuevas.length, total: filas.length, yaExisten, sinNumero: sinNumero.length });
      } else {
        const porEconomico = new Map(units.map((u) => [u.numeroEconomico, u]));
        const updates = [];
        const noEncontrados = [];
        filas.forEach((fila) => {
          const eco = String(fila[claveEconomico] ?? "").trim();
          if (!eco) return;
          const unit = porEconomico.get(eco);
          if (!unit) { noEncontrados.push(eco); return; }
          const changes = {};
          columnas.forEach((c) => {
            if (Object.prototype.hasOwnProperty.call(fila, c.header)) {
              const val = fila[c.header];
              changes[c.field] = val === undefined || val === null ? "" : String(val).trim();
            }
          });
          if (Object.keys(changes).length > 0) updates.push({ id: unit.id, changes });
        });
        if (updates.length > 0) onBulkUpdate(updates);
        setResultado({ modo, actualizadas: updates.length, total: filas.length, noEncontrados });
      }
    } catch (e) {
      console.error("No se pudo procesar el archivo", e);
      setResultado({ error: e.message || "Archivo no válido." });
    } finally {
      setCargando(false);
      if (fileInputRef.current) fileInputRef.current.value = "";
    }
  };

  return (
    <div className="modal-backdrop" onClick={onClose}>
      <div className="modal" onClick={(e) => e.stopPropagation()}>
        <div className="modal-head">
          <h2 className="modal-title">Actualizar datos</h2>
          <button className="icon-btn" onClick={onClose}><X size={18} /></button>
        </div>

        {permiteAgregar && (
          <div className="chip-row" style={{ marginBottom: 14 }}>
            <button className={`chip ${modo === "actualizar" ? "chip-active" : ""}`} onClick={() => { setModo("actualizar"); setResultado(null); }}>Actualizar unidades existentes</button>
            <button className={`chip ${modo === "agregar" ? "chip-active" : ""}`} onClick={() => { setModo("agregar"); setResultado(null); }}>Agregar unidades nuevas</button>
          </div>
        )}

        {modo === "actualizar" && categoriasActualizar.length > 1 && (
          <Field label="¿Qué se va a actualizar?">
            <select className="select" value={categoriaId} onChange={(e) => { setCategoriaId(e.target.value); setResultado(null); }}>
              {categoriasActualizar.map((c) => <option key={c.id} value={c.id}>{c.label}</option>)}
            </select>
          </Field>
        )}

        <div className="empty" style={{ margin: "12px 0", textAlign: "left" }}>
          {modo === "agregar" ? (
            <>1. Copia la plantilla (trae una fila de ejemplo). 2. Pégala en Excel con Ctrl+V y agrega una fila por cada {tipo?.toLowerCase()} nuevo, con su propio "Número económico" (no debe repetirse con uno que ya exista). 3. Guarda el archivo (.xlsx o .csv) y súbelo abajo para darlas de alta.</>
          ) : (
            <>1. Copia la plantilla con los datos actuales ({units.length} unidad{units.length === 1 ? "" : "es"}). 2. Pégala en Excel con Ctrl+V y edita solo lo que quieras corregir — no cambies la columna "Número económico", es la que identifica cada unidad. 3. Guarda el archivo (.xlsx o .csv) y súbelo abajo para aplicar los cambios.</>
          )}
        </div>

        <button className="btn btn-ghost" onClick={copiarPlantilla} disabled={rows.length === 0}>
          <Download size={14} /> {estadoCopiar === "copiado" ? "¡Copiado! Pega en Excel (Ctrl+V)" : estadoCopiar === "error" ? "No se pudo copiar" : "Copiar plantilla"}
        </button>

        <div style={{ marginTop: 18 }}>
          <label className="field-label">Subir archivo con los cambios (.xlsx o .csv)</label>
          <input
            ref={fileInputRef}
            type="file"
            accept=".xlsx,.xls,.csv,.tsv,.txt"
            className="input"
            disabled={cargando}
            onChange={(e) => { const f = e.target.files[0]; if (f) procesarArchivo(f); }}
          />
        </div>

        {cargando && <div className="empty" style={{ marginTop: 10 }}><RefreshCw size={13} style={{ verticalAlign: "-2px", marginRight: 4 }} /> Procesando archivo…</div>}

        {resultado && !resultado.error && resultado.modo === "agregar" && (
          <div className="empty" style={{ marginTop: 10, color: "var(--teal-dark)" }}>
            {resultado.agregadas} unidad{resultado.agregadas === 1 ? "" : "es"} agregada{resultado.agregadas === 1 ? "" : "s"} de {resultado.total} fila{resultado.total === 1 ? "" : "s"} leída{resultado.total === 1 ? "" : "s"}.
            {resultado.yaExisten.length > 0 && <> Ya existían y no se tocaron: {resultado.yaExisten.join(", ")}.</>}
            {resultado.sinNumero > 0 && <> {resultado.sinNumero} fila{resultado.sinNumero === 1 ? "" : "s"} sin número económico se ignoraron.</>}
          </div>
        )}
        {resultado && !resultado.error && resultado.modo === "actualizar" && (
          <div className="empty" style={{ marginTop: 10, color: "var(--teal-dark)" }}>
            {resultado.actualizadas} unidad{resultado.actualizadas === 1 ? "" : "es"} actualizada{resultado.actualizadas === 1 ? "" : "s"} de {resultado.total} fila{resultado.total === 1 ? "" : "s"} leída{resultado.total === 1 ? "" : "s"}.
            {resultado.noEncontrados.length > 0 && <> No se encontró número económico: {resultado.noEncontrados.join(", ")}.</>}
          </div>
        )}
        {resultado && resultado.error && (
          <div className="empty" style={{ marginTop: 10, color: "var(--orange)" }}>No se pudo leer el archivo: {resultado.error}</div>
        )}
      </div>
    </div>
  );
}

// Mismo patrón que ActualizarDatosModal (unidades) pero para el catálogo de Operadores: la
// columna "Nombre" es la que identifica a cada operador (no se debe editar al actualizar, igual
// que "Número económico" en unidades) y las columnas editables son Clasificación y Estatus.
function ActualizarOperadoresModal({ operadores, onClose, onBulkUpdate, onBulkAdd }) {
  const [modo, setModo] = useState("actualizar");
  const [estadoCopiar, setEstadoCopiar] = useState("idle");
  const [cargando, setCargando] = useState(false);
  const [resultado, setResultado] = useState(null);
  const fileInputRef = useRef(null);

  const headers = ["Nombre", "Clasificación", "Estatus"];
  const rows = modo === "agregar"
    ? [["Nombre del operador nuevo", "Regional", "Activo"]]
    : operadores.map((o) => [o.nombre, o.clasificacion || "", o.estatus || "Activo"]);

  const copiarPlantilla = async () => {
    try {
      await copiarTablaAlPortapapeles(headers, rows);
      setEstadoCopiar("copiado");
    } catch (e) {
      console.error("No se pudo copiar la plantilla", e);
      setEstadoCopiar("error");
    } finally {
      setTimeout(() => setEstadoCopiar("idle"), 2200);
    }
  };

  const procesarArchivo = async (file) => {
    setCargando(true);
    setResultado(null);
    try {
      const filas = await leerArchivoTabular(file);
      const claveNombre = Object.keys(filas[0] || {}).find((k) => k.trim().toLowerCase() === "nombre") || "Nombre";
      const claveClasificacion = Object.keys(filas[0] || {}).find((k) => k.trim().toLowerCase().startsWith("clasificaci")) || "Clasificación";
      const claveEstatus = Object.keys(filas[0] || {}).find((k) => k.trim().toLowerCase() === "estatus") || "Estatus";

      if (modo === "agregar") {
        const existentes = new Set(operadores.map((o) => o.nombre.trim().toLowerCase()));
        const nuevos = [];
        const yaExisten = [];
        const sinNombre = [];
        filas.forEach((fila) => {
          const nombre = String(fila[claveNombre] ?? "").trim();
          if (!nombre) { sinNombre.push(fila); return; }
          if (existentes.has(nombre.toLowerCase())) { yaExisten.push(nombre); return; }
          existentes.add(nombre.toLowerCase());
          nuevos.push({
            nombre,
            clasificacion: String(fila[claveClasificacion] ?? "").trim(),
            estatus: String(fila[claveEstatus] ?? "").trim() || "Activo",
          });
        });
        if (nuevos.length > 0) onBulkAdd(nuevos);
        setResultado({ modo, agregados: nuevos.length, total: filas.length, yaExisten, sinNombre: sinNombre.length });
      } else {
        const porNombre = new Map(operadores.map((o) => [o.nombre.trim().toLowerCase(), o]));
        const updates = [];
        const noEncontrados = [];
        filas.forEach((fila) => {
          const nombre = String(fila[claveNombre] ?? "").trim();
          if (!nombre) return;
          const operador = porNombre.get(nombre.toLowerCase());
          if (!operador) { noEncontrados.push(nombre); return; }
          const changes = {};
          if (Object.prototype.hasOwnProperty.call(fila, claveClasificacion)) {
            changes.clasificacion = String(fila[claveClasificacion] ?? "").trim();
          }
          if (Object.prototype.hasOwnProperty.call(fila, claveEstatus)) {
            const val = String(fila[claveEstatus] ?? "").trim();
            if (val) changes.estatus = val;
          }
          if (Object.keys(changes).length > 0) updates.push({ id: operador.id, changes });
        });
        if (updates.length > 0) onBulkUpdate(updates);
        setResultado({ modo, actualizados: updates.length, total: filas.length, noEncontrados });
      }
    } catch (e) {
      console.error("No se pudo procesar el archivo", e);
      setResultado({ error: e.message || "Archivo no válido." });
    } finally {
      setCargando(false);
      if (fileInputRef.current) fileInputRef.current.value = "";
    }
  };

  return (
    <div className="modal-backdrop" onClick={onClose}>
      <div className="modal" onClick={(e) => e.stopPropagation()}>
        <div className="modal-head">
          <h2 className="modal-title">Actualizar datos</h2>
          <button className="icon-btn" onClick={onClose}><X size={18} /></button>
        </div>

        <div className="chip-row" style={{ marginBottom: 14 }}>
          <button className={`chip ${modo === "actualizar" ? "chip-active" : ""}`} onClick={() => { setModo("actualizar"); setResultado(null); }}>Actualizar operadores existentes</button>
          <button className={`chip ${modo === "agregar" ? "chip-active" : ""}`} onClick={() => { setModo("agregar"); setResultado(null); }}>Agregar operadores nuevos</button>
        </div>

        <div className="empty" style={{ margin: "12px 0", textAlign: "left" }}>
          {modo === "agregar" ? (
            <>1. Copia la plantilla (trae una fila de ejemplo). 2. Pégala en Excel con Ctrl+V y agrega una fila por cada operador nuevo, con su propio "Nombre" (no debe repetirse con uno que ya exista). 3. Guarda el archivo (.xlsx o .csv) y súbelo abajo para darlos de alta.</>
          ) : (
            <>1. Copia la plantilla con los datos actuales ({operadores.length} operador{operadores.length === 1 ? "" : "es"}). 2. Pégala en Excel con Ctrl+V y edita Clasificación y/o Estatus — no cambies la columna "Nombre", es la que identifica a cada operador. 3. Guarda el archivo (.xlsx o .csv) y súbelo abajo para aplicar los cambios.</>
          )}
        </div>

        <button className="btn btn-ghost" onClick={copiarPlantilla} disabled={rows.length === 0}>
          <Download size={14} /> {estadoCopiar === "copiado" ? "¡Copiado! Pega en Excel (Ctrl+V)" : estadoCopiar === "error" ? "No se pudo copiar" : "Copiar plantilla"}
        </button>

        <div style={{ marginTop: 18 }}>
          <label className="field-label">Subir archivo con los cambios (.xlsx o .csv)</label>
          <input
            ref={fileInputRef}
            type="file"
            accept=".xlsx,.xls,.csv,.tsv,.txt"
            className="input"
            disabled={cargando}
            onChange={(e) => { const f = e.target.files[0]; if (f) procesarArchivo(f); }}
          />
        </div>

        {cargando && <div className="empty" style={{ marginTop: 10 }}><RefreshCw size={13} style={{ verticalAlign: "-2px", marginRight: 4 }} /> Procesando archivo…</div>}

        {resultado && !resultado.error && resultado.modo === "agregar" && (
          <div className="empty" style={{ marginTop: 10, color: "var(--teal-dark)" }}>
            {resultado.agregados} operador{resultado.agregados === 1 ? "" : "es"} agregado{resultado.agregados === 1 ? "" : "s"} de {resultado.total} fila{resultado.total === 1 ? "" : "s"} leída{resultado.total === 1 ? "" : "s"}.
            {resultado.yaExisten.length > 0 && <> Ya existían y no se tocaron: {resultado.yaExisten.join(", ")}.</>}
            {resultado.sinNombre > 0 && <> {resultado.sinNombre} fila{resultado.sinNombre === 1 ? "" : "s"} sin nombre se ignoraron.</>}
          </div>
        )}
        {resultado && !resultado.error && resultado.modo === "actualizar" && (
          <div className="empty" style={{ marginTop: 10, color: "var(--teal-dark)" }}>
            {resultado.actualizados} operador{resultado.actualizados === 1 ? "" : "es"} actualizado{resultado.actualizados === 1 ? "" : "s"} de {resultado.total} fila{resultado.total === 1 ? "" : "s"} leída{resultado.total === 1 ? "" : "s"}.
            {resultado.noEncontrados.length > 0 && <> No se encontró el nombre: {resultado.noEncontrados.join(", ")}.</>}
          </div>
        )}
        {resultado && resultado.error && (
          <div className="empty" style={{ marginTop: 10, color: "var(--orange)" }}>No se pudo leer el archivo: {resultado.error}</div>
        )}
      </div>
    </div>
  );
}

function PageHeader({ eyebrow, title, action }) {
  return (
    <div className="page-head">
      <div><div className="eyebrow">{eyebrow}</div><h2>{title}</h2></div>
      {action}
    </div>
  );
}

function UnitModal({ unit, allUnits, role, sessionNombre, operadores, onClose, onUpdate, onDelete, onResolverSolicitud, canAprobarSolicitudes, hideMaintenance }) {
  const [estatus, setEstatus] = useState(unit.estatus);
  const [ubicacion, setUbicacion] = useState(unit.ubicacion);
  const [operador, setOperador] = useState(unit.operador);
  const canEdit = tienePermiso(role, "catalogo.editarTodo");
  const canEdicionRapida = tienePermiso(role, "catalogo.edicionRapida");
  // El desplegable de operador (catálogo de Operadores) solo aplica a Tractor -- Dry Van y
  // Flatbed siguen con el campo de texto libre, tal cual se pidió.
  const usaCatalogoOperadores = unit.tipo === "Tractor";
  const operadoresActivos = (operadores || []).filter((o) => o.estatus === "Activo");
  const [editing, setEditing] = useState(false);
  const [form, setForm] = useState(unit);
  const [tab, setTab] = useState("detalle");
  // Mantenimiento e Inspección aplican a los 3 tipos de unidad (Tractor, Dry Van, Flatbed);
  // se ocultan cuando el modal se abre desde Seguros (hideMaintenance, no aplica ahí) y también
  // según el rol de quien esté viendo (ver PERMISOS_POR_ROL): p. ej. Tráfico no ve ninguna de
  // las dos, y Operador solo ve Inspección.
  const showMantenimiento = !hideMaintenance && tienePermiso(role, "mantenimiento.ver");
  const showInspeccion = !hideMaintenance && tienePermiso(role, "inspeccion.ver");

  const saveQuick = () => onUpdate({ estatus, ubicacion, operador });
  const saveFull = () => { onUpdate(form); setEditing(false); };

  return (
    <div className="modal-backdrop" onClick={onClose}>
      <div className="modal" onClick={(e) => e.stopPropagation()}>
        <div className="modal-head">
          <div>
            <span className="plate mono">{unit.numeroEconomico}</span>
            <h2 className="modal-title">{unit.marca} {unit.modelo} · {unit.tipo}</h2>
          </div>
          <button className="icon-btn" onClick={onClose}><X size={18} /></button>
        </div>

        {!editing && (showMantenimiento || showInspeccion) && (
          <div className="tab-row">
            <button className={`tab-btn ${tab === "detalle" ? "tab-btn-active" : ""}`} onClick={() => setTab("detalle")}>
              <ClipboardList size={14} /> Detalle
            </button>
            {showMantenimiento && (
              <button className={`tab-btn ${tab === "mantenimiento" ? "tab-btn-active" : ""}`} onClick={() => setTab("mantenimiento")}>
                <Wrench size={14} /> Mantenimiento
              </button>
            )}
            {showInspeccion && (
              <button className={`tab-btn ${tab === "inspeccion" ? "tab-btn-active" : ""}`} onClick={() => setTab("inspeccion")}>
                <Check size={14} /> Inspección
              </button>
            )}
          </div>
        )}

        {!editing && tab === "mantenimiento" && showMantenimiento ? (
          <MaintenanceTab unit={unit} onUpdate={onUpdate} />
        ) : !editing && tab === "inspeccion" && showInspeccion ? (
          <InspectionTab unit={unit} onUpdate={onUpdate} sessionNombre={sessionNombre} />
        ) : !editing && hideMaintenance ? (
          <div className="detail-grid" style={{ marginBottom: 0 }}>
            <Detail label="Estatus" value={unit.estatus} />
            <Detail label="Ubicación" value={unit.ubicacion || "—"} />
            <Detail label="Operador asignado" value={unit.operador || "—"} />
          </div>
        ) : !editing ? (
          <>
            <div className="detail-grid">
              <Detail label="Placas MX" value={unit.placas} mono />
              <Detail label="Placas US" value={unit.placasUs || "—"} mono />
              <Detail label="VIN" value={unit.vin} mono />
              <Detail label="Año" value={unit.anio} />
              <Detail label="Configuración" value={unit.configuracion || "—"} />
              <Detail label="Unidad de negocio" value={unit.businessUnit || "—"} mono />
              <Detail label="Gerente de flota" value={unit.gerenteFlota || "—"} />
              {unit.tipo === "Dry Van" && (
                <>
                  <Detail label="¿Doble estiba?" value={unit.dobleEstiba || "Sin definir"} />
                  <Detail label="¿Thermo?" value={unit.thermo || "Sin definir"} />
                  <Detail label="¿Apta para productos médicos?" value={unit.aptaProductosMedicos || "Sin definir"} />
                </>
              )}
              <Detail label="Notas" value={unit.notas || "—"} />
            </div>

            {canEdicionRapida && (
            <div className="quick-edit">
              <div className="field-inline">
                <label className="field-label">Estatus</label>
                <select className="select" value={estatus} onChange={(e) => setEstatus(e.target.value)}>
                  {ESTATUS.map((s) => <option key={s}>{s}</option>)}
                </select>
              </div>
              <div className="field-inline">
                <label className="field-label">Ubicación</label>
                <input className="input" value={ubicacion} onChange={(e) => setUbicacion(e.target.value)} />
              </div>
              <div className="field-inline">
                <label className="field-label">Operador asignado</label>
                {usaCatalogoOperadores ? (
                  <select className="select" value={operador || ""} onChange={(e) => setOperador(e.target.value)}>
                    <option value="">Sin asignar</option>
                    {operadoresActivos.map((o) => <option key={o.id} value={o.nombre}>{o.nombre}</option>)}
                    {operador && !operadoresActivos.some((o) => o.nombre === operador) && (
                      <option value={operador}>{operador} (no está en el catálogo o está inactivo)</option>
                    )}
                  </select>
                ) : (
                  <input className="input" value={operador} onChange={(e) => setOperador(e.target.value)} />
                )}
              </div>
              <button className="btn btn-primary" onClick={saveQuick}>Guardar cambios</button>
            </div>
            )}

            <h4 className="section-title"><ShieldAlert size={14} /> Vencimientos</h4>
            <div className="vence-grid">
              {checkFieldsFor(unit).map(({ field, label }) => {
                // Sin fecha capturada (frecuente en unidades que aún no tienen todos los
                // datos, p. ej. Dry Van/Flatbed recién dadas de alta): se muestra como "Sin
                // registro" en vez de calcular una urgencia sobre una fecha vacía, que antes
                // se mostraba como "Invalid Date" con un badge verde "Al corriente" engañoso.
                if (!unit[field]) {
                  return (
                    <div className="vence-card" key={field}>
                      <div className="vence-top"><span>{label}</span><Badge tone="neutral">Sin registro</Badge></div>
                      <div className="vence-date">—</div>
                    </div>
                  );
                }
                const days = daysUntil(unit[field]);
                const u = urgencyOf(days);
                return (
                  <div className="vence-card" key={field}>
                    <div className="vence-top"><span>{label}</span><Badge tone={u}>{URGENCY_LABEL[u]}</Badge></div>
                    <div className="vence-date">{fmtDate(unit[field])}</div>
                  </div>
                );
              })}
            </div>

            <DocumentSection unit={unit} onUpdate={onUpdate} />

            {unit.solicitudes && unit.solicitudes.length > 0 && (
              <>
                <h4 className="section-title"><Bell size={14} /> Solicitudes de asignación/préstamo</h4>
                <div className="history-list">
                  {unit.solicitudes.slice(0, 6).map((s, i) => {
                    const estatusSolicitud = s.estatus || "Pendiente"; // compatibilidad con solicitudes ya guardadas antes de este cambio
                    const tone = estatusSolicitud === "Aprobada" ? "ok" : estatusSolicitud === "Rechazada" ? "vencido" : "proximo";
                    return (
                      <div className="history-row history-row-solicitud" key={s.id || i}>
                        <span className="history-field">{s.tipo === "asignacion" ? "Asignación" : "Préstamo"}</span>
                        <span>{s.solicitante}{s.nota ? ` — ${s.nota}` : ""}</span>
                        <span className="history-meta">{new Date(s.fecha).toLocaleDateString("es-MX")}</span>
                        <span style={{ display: "flex", alignItems: "center", gap: 6, justifyContent: "flex-end" }}>
                          <Badge tone={tone}>{estatusSolicitud}</Badge>
                          {canAprobarSolicitudes && estatusSolicitud === "Pendiente" && s.id && (
                            <>
                              <button className="btn btn-ghost btn-sm" onClick={() => onResolverSolicitud(s.id, "Aprobada")}>Aprobar</button>
                              <button className="btn btn-ghost btn-sm" onClick={() => onResolverSolicitud(s.id, "Rechazada")}>Rechazar</button>
                            </>
                          )}
                        </span>
                      </div>
                    );
                  })}
                </div>
              </>
            )}

            {unit.historial && unit.historial.length > 0 && (
              <>
                <h4 className="section-title"><Clock size={14} /> Historial de cambios</h4>
                <div className="history-list">
                  {unit.historial.slice(0, 6).map((h, i) => (
                    <div className="history-row" key={i}>
                      <span className="history-field">{h.campo}</span>
                      <span>{fmtHistValor(h.anterior)} → {fmtHistValor(h.nuevo)}</span>
                      <span className="history-meta">{h.usuario} · {new Date(h.fecha).toLocaleDateString("es-MX")}</span>
                    </div>
                  ))}
                </div>
              </>
            )}

            <div className="modal-actions">
              {canEdit && (
                <button className="btn btn-ghost" onClick={() => setEditing(true)}><Pencil size={14} /> Editar todos los datos</button>
              )}
              {canEdit && (
                <button className="btn btn-danger" onClick={onDelete}><Trash2 size={14} /> Eliminar unidad</button>
              )}
            </div>
          </>
        ) : (
          <EditForm form={form} setForm={setForm} onCancel={() => setEditing(false)} onSave={saveFull} existingEconomicos={(allUnits || []).filter((u) => u.id !== unit.id).map((u) => u.numeroEconomico)} />
        )}
      </div>
    </div>
  );
}

function MaintenanceTab({ unit, onUpdate }) {
  // Dry Van y Flatbed son remolques: no tienen motor ni odómetro propio, así que no aplica
  // "Odómetro actual" ni el registro de mantenimiento por millaje (ver mantenimientoStatus).
  const isTrailer = unit.tipo === "Dry Van" || unit.tipo === "Flatbed";
  const [showOdoForm, setShowOdoForm] = useState(false);
  const [odoInput, setOdoInput] = useState("");
  const [selectedPos, setSelectedPos] = useState(null);
  const [tireForm, setTireForm] = useState({ numeroSerie: "", marca: "", odometro: "", tipo: "Nueva", aplicacion: "Dirección", profundidad: "", costo: "" });
  const [showMttoForm, setShowMttoForm] = useState(false);
  const [mttoInput, setMttoInput] = useState("");
  const [mttoNota, setMttoNota] = useState("");
  const [mttoCosto, setMttoCosto] = useState("");
  const [mttoTipo, setMttoTipo] = useState("Preventivo");

  const historial = unit.odometroHistorial || [];
  const odometroActual = historial.length > 0 ? historial[0].lectura : (unit.odometro || 0);
  const llantas = unit.llantas || [];
  const total = numLlantasFor(unit);
  const positions = TIRE_POSITIONS[total];

  const mttoHistorial = unit.mantenimientoHistorial || [];
  const mtto = mantenimientoStatus(unit);
  const mttoTone = mtto.sinRegistro ? null : mtto.pendiente ? "vencido" : mtto.proximo ? "proximo" : "ok";

  const saveOdometro = () => {
    const val = parseInt(odoInput, 10);
    if (!val && val !== 0) return;
    const entry = { lectura: val, fecha: new Date().toISOString() };
    onUpdate({ odometroHistorial: [entry, ...historial], odometro: val });
    setOdoInput("");
    setShowOdoForm(false);
  };

  const openMttoForm = () => {
    setMttoInput(String(odometroActual || ""));
    setMttoNota("");
    setMttoCosto("");
    setMttoTipo("Preventivo");
    setShowMttoForm(true);
  };

  const saveMantenimiento = () => {
    const costoVal = Math.max(0, parseFloat(mttoCosto) || 0);
    if (isTrailer) {
      // Sin odómetro propio, el mantenimiento de un remolque se registra solo por fecha
      // (ver mantenimientoStatus, que para Dry Van/Flatbed calcula el intervalo en meses).
      const entry = { fecha: new Date().toISOString(), nota: mttoNota.trim(), costo: costoVal, tipo: mttoTipo };
      onUpdate({ mantenimientoHistorial: [entry, ...mttoHistorial] });
      setShowMttoForm(false);
      return;
    }
    const val = parseInt(mttoInput, 10);
    if (!val && val !== 0) return;
    const entry = { odometro: val, fecha: new Date().toISOString(), nota: mttoNota.trim(), costo: costoVal, tipo: mttoTipo };
    // Registrar el mantenimiento y, ya que representa una lectura fresca del odómetro,
    // también actualiza el odómetro actual para mantener ambos datos consistentes.
    const odoEntry = { lectura: val, fecha: entry.fecha };
    onUpdate({
      mantenimientoHistorial: [entry, ...mttoHistorial],
      odometroHistorial: [odoEntry, ...historial],
      odometro: val,
    });
    setShowMttoForm(false);
  };

  const costoTotal = mttoHistorial.reduce((sum, m) => sum + (Number(m.costo) || 0), 0);
  const fmtCosto = (n) => `$${Number(n || 0).toLocaleString("es-MX", { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;

  const openPos = (posKey) => {
    setSelectedPos(posKey);
    const aplicacionDefault = posKey.startsWith("del_") ? "Dirección" : "Tracción";
    setTireForm({ numeroSerie: "", marca: "", odometro: String(odometroActual || ""), tipo: "Nueva", aplicacion: aplicacionDefault, profundidad: "", costo: "" });
  };

  const assignTire = () => {
    if (!tireForm.numeroSerie.trim()) return;
    const profundidadMm = tireForm.tipo === "Nueva" ? LLANTA_MM_NUEVA : Math.max(0, parseFloat(tireForm.profundidad) || 0);
    const costoVal = Math.max(0, parseFloat(tireForm.costo) || 0);
    const next = llantas.map((l) => (l.posicion === selectedPos && l.activa ? { ...l, activa: false } : l));
    next.unshift({
      posicion: selectedPos,
      numeroSerie: tireForm.numeroSerie.trim(),
      marca: tireForm.marca.trim(),
      // Sin odómetro propio en Dry Van/Flatbed, no se registra el "odómetro al instalar" (ver Detail).
      odometroInstalacion: isTrailer ? null : (parseInt(tireForm.odometro, 10) || 0),
      fechaInstalacion: new Date().toISOString(),
      activa: true,
      tipo: tireForm.tipo,
      aplicacion: tireForm.aplicacion,
      profundidadMm,
      vidaPct: vidaLlantaPct(profundidadMm),
      costo: costoVal,
    });
    onUpdate({ llantas: next });
    setSelectedPos(null);
  };

  const costoLlantasTotal = llantas.reduce((sum, l) => sum + (Number(l.costo) || 0), 0);

  const posActual = positions.find((p) => p.key === selectedPos);
  const llantaSel = selectedPos ? llantaActivaEn(llantas, selectedPos) : null;
  const historialPos = selectedPos ? llantasEnPosicion(llantas, selectedPos).filter((l) => !l.activa) : [];

  const intervaloTexto = mtto.porFecha ? `${MTTO_INTERVALO_MESES_TRAILER} meses` : `${MTTO_INTERVALO.toLocaleString("es-MX")} mi`;

  return (
    <div className="maint">
      {!isTrailer && (
        <div className="maint-odo">
          <div className="maint-odo-info">
            <Gauge size={18} />
            <div>
              <div className="detail-label">Odómetro actual</div>
              <div className="odo-value mono">{odometroActual ? `${odometroActual.toLocaleString("es-MX")} mi` : "Sin registro"}</div>
            </div>
          </div>
          {!showOdoForm ? (
            <button className="btn btn-ghost" onClick={() => setShowOdoForm(true)}>Actualizar odómetro</button>
          ) : (
            <div className="odo-form">
              <input className="input" type="number" placeholder="Nueva lectura" value={odoInput} onChange={(e) => setOdoInput(e.target.value)} />
              <button className="btn btn-primary" onClick={saveOdometro}>Guardar</button>
              <button className="btn btn-ghost" onClick={() => setShowOdoForm(false)}>Cancelar</button>
            </div>
          )}
        </div>
      )}

      <h4 className="section-title"><Wrench size={14} /> Mantenimiento preventivo</h4>
      <div className={`mtto-panel ${mtto.pendiente ? "mtto-panel-pendiente" : ""}`}>
        {mtto.pendiente && (
          <div className="mtto-alert">
            <AlertTriangle size={15} /> {MTTO_ESTATUS}
          </div>
        )}
        <div className="mtto-stats">
          <div className="mtto-stat">
            <div className="detail-label">Último mantenimiento</div>
            <div className="mono">
              {mtto.sinRegistro ? "Sin registro" : mtto.porFecha ? new Date(mtto.ultimo.fecha).toLocaleDateString("es-MX") : `${mtto.ultimo.odometro.toLocaleString("es-MX")} mi`}
            </div>
            {!mtto.sinRegistro && !mtto.porFecha && <div className="mtto-substat">{new Date(mtto.ultimo.fecha).toLocaleDateString("es-MX")}</div>}
          </div>
          <div className="mtto-stat">
            <div className="detail-label">{mtto.porFecha ? "Tiempo transcurrido" : "Recorrido desde entonces"}</div>
            <div className="mono">
              {mtto.sinRegistro ? "—" : mtto.porFecha ? `${mtto.mesesTranscurridos.toFixed(1)} meses` : `${mtto.diff.toLocaleString("es-MX")} mi`}
            </div>
            {!mtto.sinRegistro && (
              <div className="mtto-substat">
                {mtto.porFecha
                  ? (mtto.pendiente
                      ? `${(mtto.mesesTranscurridos - MTTO_INTERVALO_MESES_TRAILER).toFixed(1)} meses sobre el límite`
                      : `${(MTTO_INTERVALO_MESES_TRAILER - mtto.mesesTranscurridos).toFixed(1)} meses para el siguiente`)
                  : (mtto.pendiente
                      ? `${(-mtto.restante).toLocaleString("es-MX")} mi sobre el límite`
                      : `${mtto.restante.toLocaleString("es-MX")} mi para el siguiente`)}
              </div>
            )}
          </div>
        </div>
        {!mtto.sinRegistro && (
          <div className="mtto-bar-track">
            <div
              className={`mtto-bar-fill ${mtto.pendiente ? "mtto-bar-fill-over" : mtto.proximo ? "mtto-bar-fill-warn" : ""}`}
              style={{
                width: `${mtto.porFecha
                  ? Math.min(100, Math.max(0, (mtto.mesesTranscurridos / MTTO_INTERVALO_MESES_TRAILER) * 100))
                  : Math.min(100, Math.max(0, (mtto.diff / MTTO_INTERVALO) * 100))}%`,
              }}
            />
          </div>
        )}
        <div className="empty" style={{ padding: "6px 0 0" }}>Intervalo de referencia: {intervaloTexto}</div>

        {!showMttoForm ? (
          <button className="btn btn-primary" style={{ marginTop: 10 }} onClick={openMttoForm}>
            Registrar mantenimiento
          </button>
        ) : (
          <div className="quick-edit" style={{ marginTop: 12, marginBottom: 0 }}>
            <div className="field-inline">
              <label className="field-label">Tipo</label>
              <select className="select" value={mttoTipo} onChange={(e) => setMttoTipo(e.target.value)}>
                <option value="Preventivo">Mantenimiento preventivo</option>
                <option value="Reparación">Reparación</option>
              </select>
              {mttoTipo === "Reparación" && (
                <div className="empty" style={{ padding: "2px 0 0" }}>
                  Una reparación queda en el historial pero no reinicia el contador de {intervaloTexto} del mantenimiento preventivo.
                </div>
              )}
            </div>
            {!isTrailer && (
              <div className="field-inline">
                <label className="field-label">Odómetro al momento del servicio (mi)</label>
                <input className="input" type="number" value={mttoInput} onChange={(e) => setMttoInput(e.target.value)} />
              </div>
            )}
            <div className="field-inline">
              <label className="field-label">Nota (opcional)</label>
              <input className="input" value={mttoNota} onChange={(e) => setMttoNota(e.target.value)} placeholder="Servicio, taller, refacciones…" />
            </div>
            <div className="field-inline">
              <label className="field-label">Costo (opcional)</label>
              <input className="input" type="number" min="0" step="0.01" value={mttoCosto} onChange={(e) => setMttoCosto(e.target.value)} placeholder="0.00" />
            </div>
            <div style={{ display: "flex", gap: 8 }}>
              <button className="btn btn-primary" onClick={saveMantenimiento}>Guardar</button>
              <button className="btn btn-ghost" onClick={() => setShowMttoForm(false)}>Cancelar</button>
            </div>
          </div>
        )}

        {mttoHistorial.length > 0 && (
          <>
            <h4 className="section-title" style={{ marginTop: 16 }}>
              <Clock size={14} /> Historial de mantenimientos
              <span className="mtto-costo-total">Total acumulado: {fmtCosto(costoTotal)}</span>
            </h4>
            <div className="history-list">
              {mttoHistorial.slice(0, 6).map((m, i) => {
                const tipoM = m.tipo || "Preventivo";
                return (
                  <div className="history-row history-row-mtto-tipo" key={i}>
                    <span className="history-field mono">{typeof m.odometro === "number" ? `${m.odometro.toLocaleString("es-MX")} mi` : "—"}</span>
                    <span className={`tipo-tag ${tipoM === "Reparación" ? "tipo-tag-reparacion" : "tipo-tag-preventivo"}`}>{tipoM}</span>
                    <span>{m.nota || "—"}</span>
                    <span className="history-field mono">{m.costo ? fmtCosto(m.costo) : "—"}</span>
                    <span className="history-meta">{new Date(m.fecha).toLocaleDateString("es-MX")}</span>
                  </div>
                );
              })}
            </div>
          </>
        )}
      </div>

      <h4 className="section-title">
        <Disc size={14} /> Llantas ({total} posiciones — {unit.configuracion || "config. no definida"})
        {costoLlantasTotal > 0 && <span className="mtto-costo-total">Costo acumulado en llantas: {fmtCosto(costoLlantasTotal)}</span>}
      </h4>

      {!selectedPos ? (
        <div className="tire-diagram-wrap">
          <svg viewBox="0 0 320 260" className="tire-diagram">
            <rect x="70" y="15" width="180" height="230" rx="18" className="tire-chassis" />
            {positions.map((p) => {
              const activa = llantaActivaEn(llantas, p.key);
              return (
                <g key={p.key} onClick={() => openPos(p.key)} className="tire-pos" cursor="pointer">
                  <circle cx={p.x} cy={p.y} r="16" className={`tire-dot ${activa ? "tire-dot-set" : "tire-dot-empty"}`} />
                  <text x={p.x} y={p.y + 4} textAnchor="middle" className="tire-dot-label">{activa ? "●" : "+"}</text>
                </g>
              );
            })}
          </svg>
          <div className="tire-legend">
            <span><span className="tire-dot-sample tire-dot-set" /> Con llanta</span>
            <span><span className="tire-dot-sample tire-dot-empty" /> Vacía</span>
          </div>
          <div className="tire-list">
            {positions.map((p) => {
              const activa = llantaActivaEn(llantas, p.key);
              return (
                <button className="tire-row" key={p.key} onClick={() => openPos(p.key)}>
                  <span>{p.label}</span>
                  {activa ? (
                    <span className="tire-row-info">
                      <span className="mono">{activa.numeroSerie}</span>
                      {typeof activa.vidaPct === "number" && (
                        <Badge tone={vidaTone(activa.vidaPct)}>{activa.vidaPct}% vida</Badge>
                      )}
                    </span>
                  ) : (
                    <span className="empty-inline">Sin llanta</span>
                  )}
                </button>
              );
            })}
          </div>
        </div>
      ) : (
        <div className="tire-detail">
          <button className="link-btn" onClick={() => setSelectedPos(null)}><ArrowLeft size={14} /> Volver al diagrama</button>
          <h4 className="section-title" style={{ marginTop: 12 }}>{posActual.label}</h4>

          {llantaSel && (
            <div className="detail-grid" style={{ marginBottom: 14 }}>
              <Detail label="Número de llanta" value={llantaSel.numeroSerie} mono />
              <Detail label="Marca" value={llantaSel.marca || "—"} />
              <Detail label="Tipo" value={llantaSel.tipo || "—"} />
              <Detail label="Aplicación" value={llantaSel.aplicacion || "—"} />
              <Detail label="Milímetros de dibujo" value={typeof llantaSel.profundidadMm === "number" ? `${llantaSel.profundidadMm} mm` : "—"} mono />
              <Detail
                label="Vida restante"
                value={typeof llantaSel.vidaPct === "number" ? <Badge tone={vidaTone(llantaSel.vidaPct)}>{llantaSel.vidaPct}%</Badge> : "—"}
              />
              {typeof llantaSel.odometroInstalacion === "number" && (
                <Detail label="Odómetro al instalar" value={`${llantaSel.odometroInstalacion.toLocaleString("es-MX")} mi`} mono />
              )}
              <Detail label="Fecha instalación" value={new Date(llantaSel.fechaInstalacion).toLocaleDateString("es-MX")} />
              <Detail label="Costo" value={llantaSel.costo ? fmtCosto(llantaSel.costo) : "—"} mono />
            </div>
          )}

          <div className="quick-edit">
            <div className="field-label">{llantaSel ? "Reemplazar llanta" : "Agregar llanta"}</div>
            <div className="field-inline">
              <label className="field-label">Número de llanta</label>
              <input className="input" value={tireForm.numeroSerie} onChange={(e) => setTireForm({ ...tireForm, numeroSerie: e.target.value })} />
            </div>
            <div className="field-inline">
              <label className="field-label">Marca (opcional)</label>
              <input className="input" value={tireForm.marca} onChange={(e) => setTireForm({ ...tireForm, marca: e.target.value })} />
            </div>
            <div className="field-inline">
              <label className="field-label">Tipo de llanta</label>
              <select
                className="select"
                value={tireForm.tipo}
                onChange={(e) => setTireForm({ ...tireForm, tipo: e.target.value, profundidad: e.target.value === "Nueva" ? "" : tireForm.profundidad })}
              >
                {TIPOS_LLANTA.map((t) => <option key={t} value={t}>{t}</option>)}
              </select>
            </div>
            <div className="field-inline">
              <label className="field-label">Aplicación</label>
              <select className="select" value={tireForm.aplicacion} onChange={(e) => setTireForm({ ...tireForm, aplicacion: e.target.value })}>
                {APLICACIONES_LLANTA.map((a) => <option key={a} value={a}>{a}</option>)}
              </select>
            </div>
            {tireForm.tipo === "Nueva" ? (
              <div className="empty" style={{ padding: "2px 0" }}>
                Llanta nueva: {LLANTA_MM_NUEVA} mm de dibujo (100% de vida) — se registra automáticamente.
              </div>
            ) : (
              <div className="field-inline">
                <label className="field-label">Milímetros de dibujo actuales</label>
                <input
                  className="input"
                  type="number"
                  step="0.5"
                  min="0"
                  value={tireForm.profundidad}
                  onChange={(e) => setTireForm({ ...tireForm, profundidad: e.target.value })}
                  placeholder={`de 0 a ${LLANTA_MM_NUEVA} mm`}
                />
                {tireForm.profundidad !== "" && (
                  <div className="empty" style={{ padding: "2px 0 0" }}>
                    Vida restante estimada: <b>{vidaLlantaPct(tireForm.profundidad)}%</b>
                  </div>
                )}
              </div>
            )}
            {!isTrailer && (
              <div className="field-inline">
                <label className="field-label">Odómetro al colocarla</label>
                <input className="input" type="number" value={tireForm.odometro} onChange={(e) => setTireForm({ ...tireForm, odometro: e.target.value })} />
              </div>
            )}
            <div className="field-inline">
              <label className="field-label">Costo (opcional)</label>
              <input className="input" type="number" min="0" step="0.01" value={tireForm.costo} onChange={(e) => setTireForm({ ...tireForm, costo: e.target.value })} placeholder="0.00" />
            </div>
            <button className="btn btn-primary" onClick={assignTire}>{llantaSel ? "Guardar reemplazo" : "Guardar llanta"}</button>
          </div>

          {historialPos.length > 0 && (
            <>
              <h4 className="section-title" style={{ marginTop: 16 }}><Clock size={14} /> Historial de esta posición</h4>
              <div className="history-list">
                {historialPos.map((l, i) => (
                  <div className="history-row history-row-mtto" key={i}>
                    <span className="history-field mono">{l.numeroSerie}</span>
                    <span>
                      {l.tipo || "—"} · {l.aplicacion || "—"} · {typeof l.profundidadMm === "number" ? `${l.profundidadMm} mm` : "—"}
                      {typeof l.vidaPct === "number" ? ` · ${l.vidaPct}% vida` : ""}
                    </span>
                    <span className="history-field mono">{l.costo ? fmtCosto(l.costo) : "—"}</span>
                    <span className="history-meta">{new Date(l.fechaInstalacion).toLocaleDateString("es-MX")}</span>
                  </div>
                ))}
              </div>
            </>
          )}
        </div>
      )}
    </div>
  );
}

function placasStatusDe(unit) {
  // Dry Van y Flatbed son remolques dados de alta solo con placa US (ver EditForm: para ellos
  // ni siquiera existe el campo "Placas MX"), así que su DVIR solo verifica la placa US.
  const isTrailer = unit.tipo === "Dry Van" || unit.tipo === "Flatbed";
  const mx = (unit.placas || "").trim();
  const us = (unit.placasUs || "").trim();
  if (isTrailer) {
    return { mx: "", us, completas: !!us, faltante: us ? null : "US" };
  }
  const completas = !!mx && !!us;
  let faltante = null;
  if (!mx && !us) faltante = "Ambas";
  else if (!mx) faltante = "MX";
  else if (!us) faltante = "US";
  return { mx, us, completas, faltante };
}

function InspectionTab({ unit, onUpdate, sessionNombre }) {
  // Dry Van y Flatbed no tienen motor ni odómetro propio, así que su DVIR no pide nivel de
  // diesel ni lectura de odómetro -- solo placas + el checklist de seguridad con calificación.
  const isTrailer = unit.tipo === "Dry Van" || unit.tipo === "Flatbed";
  const inspecciones = unit.inspecciones || [];
  const odometroHistorial = unit.odometroHistorial || [];
  const blank = () => Object.fromEntries(INSPECCION_ITEMS.map((it) => [it, "bien"]));
  const [showForm, setShowForm] = useState(false);
  const [operador, setOperador] = useState(unit.operador || "");
  const [odometroInput, setOdometroInput] = useState("");
  const [nivelDiesel, setNivelDiesel] = useState(NIVEL_DIESEL_OPTIONS[0]);
  const [items, setItems] = useState(blank());
  const [notas, setNotas] = useState("");
  // Fotos de daño por ítem reprobado: { [item]: [{ id, dataUrl }] }. Se comprimen en el
  // navegador (ver comprimirImagen) antes de guardarse para no llenar de datos pesados cada
  // inspección -- ver nota en la función sobre el porqué.
  const [fotosDanio, setFotosDanio] = useState({});
  const [subiendoFoto, setSubiendoFoto] = useState(null);

  const openForm = () => {
    setOperador(unit.operador || "");
    setOdometroInput(String(odometroActualDe(unit) || ""));
    setNivelDiesel(NIVEL_DIESEL_OPTIONS[0]);
    setItems(blank());
    setNotas("");
    setFotosDanio({});
    setShowForm(true);
  };

  const toggleItem = (item) => setItems((prev) => ({ ...prev, [item]: prev[item] === "bien" ? "falla" : "bien" }));

  const agregarFoto = async (item, file) => {
    if (!file) return;
    setSubiendoFoto(item);
    try {
      const dataUrl = await comprimirImagen(file);
      setFotosDanio((prev) => ({ ...prev, [item]: [...(prev[item] || []), { id: genId(), dataUrl }] }));
    } catch (e) {
      console.error("No se pudo procesar la foto:", e);
    } finally {
      setSubiendoFoto(null);
    }
  };
  const quitarFoto = (item, id) => {
    setFotosDanio((prev) => ({ ...prev, [item]: (prev[item] || []).filter((f) => f.id !== id) }));
  };

  // Calificación 0-100 según la tabla de relevancia (INSPECCION_PESOS): reemplaza la regla anterior
  // de "una sola falla tumba toda la inspección" -- ahora cada ítem resta su propio peso y, arriba
  // de INSPECCION_APTA_UMBRAL (75), la unidad queda "Apta para laborar".
  const calificacion = calificacionInspeccion(items);
  const dieselBajo = !isTrailer && NIVEL_DIESEL_ALERTA.includes(nivelDiesel);
  const placas = placasStatusDe(unit);

  const saveInspeccion = () => {
    const odoVal = isTrailer ? null : parseInt(odometroInput, 10);
    if (!operador.trim()) return;
    if (!isTrailer && !odoVal && odoVal !== 0) return;
    const fecha = new Date().toISOString();
    // Solo se guardan fotos de los ítems que quedaron en falla al momento de guardar -- si el
    // usuario adjuntó una foto y luego volvió a marcar ese ítem como "bien", no se conserva.
    const fotos = Object.fromEntries(
      Object.entries(fotosDanio).filter(([item, arr]) => items[item] === "falla" && arr && arr.length > 0)
    );
    const entry = {
      fecha,
      operador: operador.trim(),
      capturadoPor: sessionNombre || "—", // quién capturó la inspección en la app (no confundir con "operador", el chofer de la unidad)
      placasMx: placas.mx,
      placasUs: placas.us,
      placasCompletas: placas.completas,
      placasFaltante: placas.faltante,
      items: { ...items },
      fotosDanio: fotos,
      notas: notas.trim(),
      calificacion,
      estado: estadoInspeccion(calificacion),
      ...(isTrailer ? {} : { odometro: odoVal, nivelDiesel, dieselBajo }),
    };
    const updates = { inspecciones: [entry, ...inspecciones] };
    if (!isTrailer) {
      // La lectura de odómetro capturada en la inspección también actualiza el odómetro general de
      // la unidad (odometroHistorial/odometro), que es lo que usa la Asignación de Diesel para
      // calcular las millas recorridas -- así una inspección nueva se refleja de inmediato ahí.
      if (dieselBajo) {
        // Cuando la inspección genera una solicitud de diesel, el odómetro de la unidad solo puede
        // avanzar: si la lectura capturada es mayor a la ya registrada se actualiza, y si es igual o
        // menor se conserva la actual -- nunca se permite que retroceda por esta vía.
        const actual = odometroActualDe(unit);
        if (odoVal > actual) {
          updates.odometroHistorial = [{ lectura: odoVal, fecha }, ...odometroHistorial];
          updates.odometro = odoVal;
        }
      } else {
        updates.odometroHistorial = [{ lectura: odoVal, fecha }, ...odometroHistorial];
        updates.odometro = odoVal;
      }
    }
    onUpdate(updates);
    setShowForm(false);
    setFotosDanio({});
  };

  const ultima = inspecciones[0];
  const ultimaDieselBajo = !isTrailer && dieselBajoDe(ultima);

  return (
    <div className="maint">
      <h4 className="section-title"><Check size={14} /> Inspección diaria (DVIR)</h4>

      {ultima && (
        <div className={`mtto-panel ${!inspeccionEsApta(ultima) || !ultima.placasCompletas || ultimaDieselBajo ? "mtto-panel-pendiente" : ""}`} style={{ marginBottom: 16 }}>
          {!inspeccionEsApta(ultima) && (
            <div className="mtto-alert"><AlertTriangle size={15} /> Última inspección: no apta para laborar</div>
          )}
          {!ultima.placasCompletas && (
            <div className="mtto-alert"><AlertTriangle size={15} /> Falta placa {ultima.placasFaltante} en la última inspección</div>
          )}
          {ultimaDieselBajo && (
            <div className="mtto-alert"><Fuel size={15} /> Nivel de diesel bajo ({ultima.nivelDiesel}) — solicitar diesel</div>
          )}
          <div className="mtto-stats">
            <div className="mtto-stat">
              <div className="detail-label">Última inspección</div>
              <div className="mono">{fmtFechaHora(ultima.fecha)}</div>
              <div className="mtto-substat">Operador: {ultima.operador}</div>
              <div className="mtto-substat">Capturada por: {ultima.capturadoPor || "—"}</div>
            </div>
            <div className="mtto-stat">
              <div className="detail-label">Resultado</div>
              <Badge tone={!inspeccionEsApta(ultima) ? "vencido" : "ok"}>{ultima.estado}</Badge>
            </div>
            <div className="mtto-stat">
              <div className="detail-label">Calificación</div>
              <div className="mono">{typeof ultima.calificacion === "number" ? `${ultima.calificacion}/100` : "—"}</div>
            </div>
            <div className="mtto-stat">
              <div className="detail-label">Placas</div>
              {ultima.placasCompletas ? (
                <Badge tone="ok">{isTrailer ? "Completa (US)" : "Completas (MX + US)"}</Badge>
              ) : (
                <Badge tone="vencido">Falta {ultima.placasFaltante}</Badge>
              )}
            </div>
            {!isTrailer && (
              <div className="mtto-stat">
                <div className="detail-label">Nivel de diesel</div>
                {ultimaDieselBajo ? (
                  <Badge tone="vencido">{ultima.nivelDiesel}</Badge>
                ) : (
                  <div className="mono">{ultima.nivelDiesel || "—"}</div>
                )}
              </div>
            )}
          </div>
        </div>
      )}

      {!showForm ? (
        <button className="btn btn-primary" onClick={openForm}>Registrar inspección</button>
      ) : (
        <div className="quick-edit" style={{ marginTop: 4, marginBottom: 16 }}>
          <div className="field-inline">
            <label className="field-label">Operador</label>
            <input className="input" value={operador} onChange={(e) => setOperador(e.target.value)} placeholder="Nombre del operador" />
          </div>
          {!isTrailer && (
            <div className="field-inline">
              <label className="field-label">Odómetro actual</label>
              <input className="input" type="number" value={odometroInput} onChange={(e) => setOdometroInput(e.target.value)} placeholder="Odómetro actual" />
            </div>
          )}
          <div className="field-inline">
            <label className="field-label">Placas</label>
            {placas.completas ? (
              <div className="placas-check placas-check-ok"><Check size={14} /> {isTrailer ? `Placa US registrada (${placas.us})` : `Ambas placas registradas (MX: ${placas.mx} / US: ${placas.us})`}</div>
            ) : (
              <div className="placas-check placas-check-falta">
                <AlertTriangle size={14} /> Falta placa {placas.faltante === "Ambas" ? "MX y US" : placas.faltante}
              </div>
            )}
          </div>
          {!isTrailer && (
          <div className="field-inline">
            <label className="field-label">Nivel de diesel</label>
            <select className="select" value={nivelDiesel} onChange={(e) => setNivelDiesel(e.target.value)}>
              {NIVEL_DIESEL_OPTIONS.map((n) => <option key={n} value={n}>{n}</option>)}
            </select>
            {dieselBajo && (
              <div className="diesel-bajo-alert"><Fuel size={14} /> Nivel bajo — solicitar diesel</div>
            )}
          </div>
          )}
          <div className="check-list">
            {INSPECCION_ITEMS.map((item) => {
              const enFalla = items[item] === "falla";
              const fotos = fotosDanio[item] || [];
              return (
                <div key={item} className="check-item-wrap">
                  <button
                    type="button"
                    className={`check-item ${enFalla ? "check-item-falla" : "check-item-bien"}`}
                    onClick={() => toggleItem(item)}
                  >
                    <span>{item}</span>
                    <Badge tone={enFalla ? "vencido" : "ok"}>{enFalla ? "Falla" : "Bien"}</Badge>
                  </button>
                  {enFalla && (
                    <div className="foto-danio-grid">
                      {fotos.map((f) => (
                        <div className="foto-danio-thumb" key={f.id}>
                          <img src={f.dataUrl} alt={`Foto de daño — ${item}`} />
                          <button type="button" onClick={() => quitarFoto(item, f.id)} title="Quitar foto">
                            <X size={10} />
                          </button>
                        </div>
                      ))}
                      <label className="foto-danio-item" style={{ cursor: "pointer" }}>
                        <span className="foto-danio-thumb foto-danio-add">
                          {subiendoFoto === item ? <RefreshCw size={16} className="spin" /> : <Camera size={16} />}
                          <input
                            type="file"
                            accept="image/*"
                            capture="environment"
                            style={{ display: "none" }}
                            disabled={subiendoFoto === item}
                            onChange={(e) => {
                              const file = e.target.files && e.target.files[0];
                              agregarFoto(item, file);
                              e.target.value = "";
                            }}
                          />
                        </span>
                        <span className="foto-danio-label">{subiendoFoto === item ? "Procesando…" : "Agregar foto"}</span>
                      </label>
                    </div>
                  )}
                </div>
              );
            })}
          </div>
          <div className="empty" style={{ padding: "6px 0 0" }}>
            Calificación estimada: <b>{calificacion}/100</b> — {calificacion > INSPECCION_APTA_UMBRAL ? "Apta para laborar" : "No apta para laborar"} (umbral: más de {INSPECCION_APTA_UMBRAL})
          </div>
          <div className="field-inline">
            <label className="field-label">Notas (opcional)</label>
            <input className="input" value={notas} onChange={(e) => setNotas(e.target.value)} placeholder="Observaciones…" />
          </div>
          <div style={{ display: "flex", gap: 8 }}>
            <button className="btn btn-primary" onClick={saveInspeccion}>Guardar inspección</button>
            <button className="btn btn-ghost" onClick={() => setShowForm(false)}>Cancelar</button>
          </div>
        </div>
      )}

      {inspecciones.length > 0 && (
        <>
          <h4 className="section-title"><Clock size={14} /> Historial de inspecciones</h4>
          <div className="history-list">
            {inspecciones.slice(0, 8).map((insp, i) => {
              const totalFotos = Object.values(insp.fotosDanio || {}).reduce((sum, arr) => sum + (arr ? arr.length : 0), 0);
              return (
                <div className="history-row history-row-insp" key={i}>
                  <span className="history-field">{insp.operador}</span>
                  <span className="history-field">
                    {insp.placasCompletas ? <Badge tone="ok">Completas</Badge> : <Badge tone="vencido">Falta {insp.placasFaltante}</Badge>}
                  </span>
                  <span>
                    <Badge tone={!inspeccionEsApta(insp) ? "vencido" : "ok"}>{insp.estado}</Badge>
                    {insp.notas ? ` — ${insp.notas}` : ""}
                    {totalFotos > 0 && (
                      <span className="history-meta" style={{ display: "inline-flex", alignItems: "center", gap: 3, marginLeft: 6 }}>
                        <Camera size={11} /> {totalFotos}
                      </span>
                    )}
                  </span>
                  <span className="history-field">
                    {isTrailer
                      ? (typeof insp.calificacion === "number" ? `${insp.calificacion}/100` : "—")
                      : (dieselBajoDe(insp) ? <Badge tone="vencido">{insp.nivelDiesel}</Badge> : (insp.nivelDiesel || "—"))}
                  </span>
                  <span className="history-meta">
                    <div className="mono">{fmtFechaHora(insp.fecha)}</div>
                    <div>{insp.capturadoPor || "—"}</div>
                  </span>
                </div>
              );
            })}
          </div>
        </>
      )}
    </div>
  );
}

function DocumentSection({ unit, onUpdate }) {
  const documentos = unit.documentos || [];
  const [tipo, setTipo] = useState(DOCUMENTO_TIPOS[0]);
  const [error, setError] = useState("");
  const inputRef = useRef(null);

  const handleFile = (e) => {
    const file = e.target.files && e.target.files[0];
    if (!file) return;
    setError("");
    if (file.size > DOCUMENTO_MAX_BYTES) {
      setError(`El archivo supera el límite de ${(DOCUMENTO_MAX_BYTES / (1024 * 1024)).toFixed(0)} MB.`);
      if (inputRef.current) inputRef.current.value = "";
      return;
    }
    const reader = new FileReader();
    reader.onload = () => {
      const entry = {
        nombre: file.name,
        tipo,
        dataUrl: reader.result,
        fecha: new Date().toISOString(),
      };
      onUpdate({ documentos: [entry, ...documentos] });
      if (inputRef.current) inputRef.current.value = "";
    };
    reader.onerror = () => setError("No se pudo leer el archivo.");
    reader.readAsDataURL(file);
  };

  const removeDoc = (idx) => {
    onUpdate({ documentos: documentos.filter((_, i) => i !== idx) });
  };

  return (
    <>
      <h4 className="section-title"><ClipboardList size={14} /> Documentos adjuntos</h4>
      <div className="doc-upload">
        <select className="select" value={tipo} onChange={(e) => setTipo(e.target.value)}>
          {DOCUMENTO_TIPOS.map((t) => <option key={t}>{t}</option>)}
        </select>
        <input ref={inputRef} className="input" type="file" accept="application/pdf,image/*" onChange={handleFile} />
      </div>
      {error && <div className="doc-error">{error}</div>}
      {documentos.length === 0 ? (
        <div className="empty" style={{ padding: "6px 0 14px" }}>Sin documentos adjuntos.</div>
      ) : (
        <div className="history-list" style={{ marginBottom: 16 }}>
          {documentos.map((d, i) => (
            <div className="history-row doc-row" key={i}>
              <span className="history-field">{d.tipo}</span>
              <a href={d.dataUrl} target="_blank" rel="noopener noreferrer">{d.nombre}</a>
              <span className="history-meta">{new Date(d.fecha).toLocaleDateString("es-MX")}</span>
              <button className="icon-btn" onClick={() => removeDoc(i)}><Trash2 size={14} /></button>
            </div>
          ))}
        </div>
      )}
    </>
  );
}

function Detail({ label, value, mono }) {
  return <div className="detail-item"><span className="detail-label">{label}</span><span className={mono ? "mono" : ""}>{value}</span></div>;
}

function EditForm({ form, setForm, onCancel, onSave, existingEconomicos = [] }) {
  const set = (k) => (e) => setForm({ ...form, [k]: e.target.value });
  // Dry Van y Flatbed son remolques: no traen seguro propio, ni trámites mexicanos, ni
  // IRP/IFTA (van a nombre del tractor -- ver checkFieldsFor), así que su formulario de
  // edición se reduce a los datos que sí aplican. La fumigación es exclusiva de Dry Van
  // (caja cerrada); el Flatbed no la necesita.
  const isTrailer = form.tipo === "Dry Van" || form.tipo === "Flatbed";
  // Placa americana: solo aplica a tractocamiones cuya unidad de negocio opera en EU
  // (US Local / US OTR / OTR) -- ver US_PLATE_BUSINESS_UNITS. Para el resto de unidades
  // de negocio el campo se bloquea en "N/A" (se normaliza al guardar, ver normalizarPlacaAmericana).
  const requierePlacaUS = !isTrailer && aplicaPlacaAmericana(form.tipo, form.businessUnit);
  // Validación (ver validarUnidad): número económico repetido y VIN de 17 caracteres. Solo
  // bloquea el botón Guardar de este formulario -- no afecta datos ya guardados sin tocar.
  const errores = validarUnidad(form, existingEconomicos);
  return (
    <div className="edit-form">
      <div className="form-grid">
        <Field label="Número económico" error={errores.numeroEconomico}>
          <input className={`input ${errores.numeroEconomico ? "input-invalid" : ""}`} value={form.numeroEconomico} onChange={set("numeroEconomico")} />
        </Field>
        <Field label="Tipo">
          <select className="select" value={form.tipo} onChange={set("tipo")}>{TIPOS.map((t) => <option key={t}>{t}</option>)}</select>
        </Field>
        {isTrailer ? (
          <>
            <Field label="VIN" error={errores.vin}>
              <input className={`input ${errores.vin ? "input-invalid" : ""}`} value={form.vin} onChange={set("vin")} maxLength={17} />
            </Field>
            <Field label="Año"><input className="input" value={form.anio} onChange={set("anio")} /></Field>
            <Field label="Placas US"><input className="input" value={form.placasUs || ""} onChange={set("placasUs")} /></Field>
            {form.tipo === "Dry Van" && (
              <>
                <Field label="Vencimiento fumigación (semestral)"><input type="date" className="input" value={form.fumigacionVencimiento || ""} onChange={set("fumigacionVencimiento")} /></Field>
                <Field label="¿Doble estiba?">
                  <select className="select" value={form.dobleEstiba || ""} onChange={set("dobleEstiba")}>
                    <option value="">Sin definir</option>
                    <option value="Sí">Sí</option>
                    <option value="No">No</option>
                  </select>
                </Field>
                <Field label="¿Thermo?">
                  <select className="select" value={form.thermo || ""} onChange={set("thermo")}>
                    <option value="">Sin definir</option>
                    <option value="Sí">Sí</option>
                    <option value="No">No</option>
                  </select>
                </Field>
                <Field label="¿Apta para productos médicos?">
                  <select className="select" value={form.aptaProductosMedicos || ""} onChange={set("aptaProductosMedicos")}>
                    <option value="">Sin definir</option>
                    <option value="Sí">Sí</option>
                    <option value="No">No</option>
                  </select>
                </Field>
              </>
            )}
          </>
        ) : (
          <>
            <Field label="Configuración"><input className="input" placeholder="Daycab / Sleeper" value={form.configuracion || ""} onChange={set("configuracion")} /></Field>
            <Field label="Marca"><input className="input" value={form.marca} onChange={set("marca")} /></Field>
            <Field label="Modelo"><input className="input" value={form.modelo} onChange={set("modelo")} /></Field>
            <Field label="Año"><input className="input" value={form.anio} onChange={set("anio")} /></Field>
            <Field label="Placas MX"><input className="input" value={form.placas} onChange={set("placas")} /></Field>
            <Field label="Placas US">
              <input
                className="input"
                value={requierePlacaUS ? (form.placasUs || "") : "N/A"}
                onChange={set("placasUs")}
                disabled={!requierePlacaUS}
                title={requierePlacaUS ? "" : "Unidad de negocio nacional: no aplica placa americana"}
              />
            </Field>
            <Field label="VIN" error={errores.vin}>
              <input className={`input ${errores.vin ? "input-invalid" : ""}`} value={form.vin} onChange={set("vin")} maxLength={17} />
            </Field>
            <Field label="Unidad de negocio">
              <select className="select" value={form.businessUnit || ""} onChange={set("businessUnit")}>
                <option value="">Sin asignar</option>
                {BUSINESS_UNIT_OPTIONS.map((bu) => <option key={bu} value={bu}>{bu}</option>)}
                {form.businessUnit && !BUSINESS_UNIT_OPTIONS.includes(form.businessUnit) && (
                  <option value={form.businessUnit}>{form.businessUnit} (valor anterior)</option>
                )}
              </select>
            </Field>
            <Field label="Gerente de flota"><input className="input" value={form.gerenteFlota || ""} onChange={set("gerenteFlota")} /></Field>
            <Field label="Aseguradora Seguro USA"><input className="input" value={form.seguroUsaAseguradora || ""} onChange={set("seguroUsaAseguradora")} /></Field>
            <Field label="Número de póliza Seguro USA"><input className="input mono" value={form.seguroUsaPoliza || ""} onChange={set("seguroUsaPoliza")} /></Field>
            <Field label="Vencimiento Seguro USA"><input type="date" className="input" value={form.seguroUsaVencimiento || ""} onChange={set("seguroUsaVencimiento")} /></Field>
            <Field label="Radio de cobertura (Seguro USA)"><input className="input" placeholder="p. ej. 0 - 50 mi" value={form.seguroUsaRadioCobertura || ""} onChange={set("seguroUsaRadioCobertura")} /></Field>
            <Field label="Aseguradora Seguro MX"><input className="input" value={form.seguroMxAseguradora || ""} onChange={set("seguroMxAseguradora")} /></Field>
            <Field label="Número de póliza Seguro MX"><input className="input mono" value={form.seguroMxPoliza || ""} onChange={set("seguroMxPoliza")} /></Field>
            <Field label="Vencimiento Seguro MX"><input type="date" className="input" value={form.seguroMxVencimiento || ""} onChange={set("seguroMxVencimiento")} /></Field>
            <Field label="Vencimiento tarjeta circulación"><input type="date" className="input" value={form.tarjetaCirculacion || ""} onChange={set("tarjetaCirculacion")} /></Field>
            <Field label="Vencimiento ecológico"><input type="date" className="input" value={form.ecologico || ""} onChange={set("ecologico")} /></Field>
            <Field label="Vencimiento físico-mecánico"><input type="date" className="input" value={form.fisicomecanico || ""} onChange={set("fisicomecanico")} /></Field>
            <Field label="Vencimiento permiso IRP"><input type="date" className="input" value={form.irpVencimiento || ""} onChange={set("irpVencimiento")} /></Field>
            <Field label="Vencimiento permiso IFTA"><input type="date" className="input" value={form.iftaVencimiento || ""} onChange={set("iftaVencimiento")} /></Field>
            <Field label="Meta de diesel (mi/gal)"><input type="number" min="0" step="0.1" className="input" value={form.dieselMeta || ""} onChange={set("dieselMeta")} /></Field>
            <Field label="Notas" full><textarea className="input" rows={2} value={form.notas} onChange={set("notas")} /></Field>
          </>
        )}
      </div>
      <div className="modal-actions">
        <button className="btn btn-ghost" onClick={onCancel}>Cancelar</button>
        <button className="btn btn-primary" disabled={Object.keys(errores).length > 0} onClick={onSave}>Guardar</button>
      </div>
    </div>
  );
}

function Field({ label, children, full, error }) {
  return (
    <div className={`field ${full ? "field-full" : ""}`}>
      <label className="field-label">{label}</label>
      {children}
      {error && <div className="field-error">{error}</div>}
    </div>
  );
}

function AddModal({ onClose, onAdd, existingEconomicos = [] }) {
  const [form, setForm] = useState({
    numeroEconomico: "", tipo: "Tractor", configuracion: "", marca: "", modelo: "", anio: new Date().getFullYear(),
    placas: "", placasUs: "", vin: "", businessUnit: "", gerenteFlota: "", estatus: "Activo", ubicacion: "", operador: "",
    seguroUsaAseguradora: "", seguroUsaPoliza: "", seguroUsaVencimiento: "", seguroUsaRadioCobertura: "",
    seguroMxAseguradora: "", seguroMxPoliza: "", seguroMxVencimiento: "",
    tarjetaCirculacion: "", ecologico: "", fisicomecanico: "",
    irpVencimiento: "", iftaVencimiento: "", fumigacionVencimiento: "",
    dobleEstiba: "", thermo: "", aptaProductosMedicos: "", dieselMeta: "", notas: "",
  });
  const set = (k) => (e) => setForm({ ...form, [k]: e.target.value });
  // Dry Van/Flatbed no traen placas MX (ver EditForm -- ese campo ni siquiera se muestra para
  // ellos), así que para esos tipos la placa que identifica a la unidad es la US.
  const isTrailer = form.tipo === "Dry Van" || form.tipo === "Flatbed";
  const valid = form.numeroEconomico.trim() && form.vin.trim() && (isTrailer ? form.placasUs.trim() : form.placas.trim());
  return (
    <div className="modal-backdrop" onClick={onClose}>
      <div className="modal" onClick={(e) => e.stopPropagation()}>
        <div className="modal-head">
          <h2 className="modal-title">Agregar unidad</h2>
          <button className="icon-btn" onClick={onClose}><X size={18} /></button>
        </div>
        <EditForm form={form} setForm={setForm} onCancel={onClose} onSave={() => valid && onAdd(form)} existingEconomicos={existingEconomicos} />
      </div>
    </div>
  );
}

